// RustyBunsConfig -> .rustybuns/alchemy.run.ts
// Targets alchemy 2.0.0-beta.77 (Infrastructure-as-Effects). Async Worker
// form: no Effect in the app bundle; bindings declared via `env`, typed via
// Cloudflare.InferEnv. The generated file is readable and committable; the
// eject path is "keep this file, delete the config".

import type { Binding, RustyBunsConfig } from "../config.ts";

const ident = (s: string) => s.replace(/[^A-Za-z0-9_]/g, "_");

function resource(name: string, b: Binding): string | null {
  const id = ident(name);
  switch (b.type) {
    case "d1":
      return `export const ${id} = Cloudflare.D1.Database("${name}"${b.migrationsDir ? `, { migrations: "${b.migrationsDir}" }` : ""});`;
    case "kv":
      return `export const ${id} = Cloudflare.KV.Namespace("${name}");`;
    case "r2":
      return `export const ${id} = Cloudflare.R2.Bucket("${name}");`;
    case "durable_object":
      // Async Workers bind a DO exported by `main` with Cloudflare.DurableObject
      // in `env` (src/Cloudflare/Workers/DurableObject.ts, "Async Workers").
      // Not a top-level resource: it is created inline in env below.
      return null;
    case "var":
    case "secret":
      return null;
  }
}

export function generateAlchemy(c: RustyBunsConfig): string {
  if (!c.worker) throw new Error("this config has no worker section (desktop-only app); there is no edge stack to generate");
  const lines: string[] = [];
  lines.push(`// GENERATED by rustybuns from rustybuns.config.ts. Edit the config, or eject:`);
  lines.push(`//   rustybuns eject   (keeps this file, you own it from then on)`);
  lines.push(`import * as Alchemy from "alchemy";`);
  lines.push(`import * as Cloudflare from "alchemy/Cloudflare";`);
  lines.push(`import * as Command from "alchemy/Command";`);
  if (c.targets.box) lines.push(`import * as Hetzner from "alchemy/Hetzner";`);
  lines.push(`import * as Effect from "effect/Effect";`);
  lines.push(`import * as Config from "effect/Config";`);
  if (c.targets.box) lines.push(`import * as Layer from "effect/Layer";`);
  lines.push(``);

  const envEntries: string[] = [];
  for (const [name, b] of Object.entries(c.bindings)) {
    const r = resource(name, b);
    if (r) { lines.push(r); envEntries.push(`${name}: ${ident(name)}`); }
    else if (b.type === "durable_object")
      envEntries.push(`${name}: Cloudflare.DurableObject("${name}", { className: "${b.className}"${b.scriptName ? `, scriptName: "${b.scriptName}"` : ""} })`);
    else if (b.type === "var") envEntries.push(`${name}: ${JSON.stringify(b.value)}`);
    else if (b.type === "secret") envEntries.push(`${name}: Config.redacted("${name}")`);
  }
  lines.push(``);

  if (c.worker.build) {
    lines.push(`// Build the app (RWSDK: vite build -> dist/worker + dist/client) before deploy.`);
    lines.push(`export const Build = Command.Build("Build", { command: ${JSON.stringify(c.worker.build)}, outdir: "dist" });`);
    lines.push(``);
  }

  lines.push(`export const Worker = Cloudflare.Worker("Worker", {`);
  lines.push(`  main: ${JSON.stringify(c.worker.builtMain ?? c.worker.main)},`);
  if (c.worker.builtMain) lines.push(`  bundle: false,  // vite already produced a runtime-ready ESM bundle`);
  if (c.worker.assets) {
    lines.push(`  assets: {`);
    lines.push(`    directory: ${JSON.stringify(c.worker.assets)},`);
    if (c.worker.runWorkerFirst) lines.push(`    runWorkerFirst: ${JSON.stringify(c.worker.runWorkerFirst)},`);
    lines.push(`  },`);
  }
  lines.push(`  compatibility: { date: ${JSON.stringify(c.worker.compatibilityDate)}, flags: ${JSON.stringify(c.worker.compatibilityFlags)} },`);
  if (c.targets.edge?.domain) lines.push(`  domain: ${JSON.stringify(c.targets.edge.domain)},`);
  lines.push(`  env: { ${envEntries.join(", ")} },`);
  lines.push(`});`);
  lines.push(``);
  lines.push(`/** The typed env the Worker AND the desktop shell compile against. */`);
  lines.push(`export type WorkerEnv = Cloudflare.InferEnv<typeof Worker>;`);
  lines.push(``);

  if (c.targets.box) {
    const b = c.targets.box;
    lines.push(`// ---- box target (Hetzner) ------------------------------------------------`);
    lines.push(`// Hetzner.Service ships a bundled fetch program under systemd. Whether it`);
    lines.push(`// runs under Bun or Node on the box is NOT confirmed in the beta.77 docs;`);
    lines.push(`// if Node, swap for Hetzner.Server + cloud-init running the compiled binary.`);
    lines.push(`export const Box = Hetzner.Server("Box", { type: ${JSON.stringify(b.serverType ?? "cpx22")}, location: ${JSON.stringify(b.region ?? "fsn1")} });`);
    lines.push(`export const Data = Hetzner.Volume("Data", { server: Box, size: 10, mount: "/data" });`);
    lines.push(`export const Service = Hetzner.Service("Service", { server: Box, main: "./.rustybuns/box.ts", port: 3000, env: { DATA_DIR: "/data" } });`);
    lines.push(``);
  }

  lines.push(`export default Alchemy.Stack(`);
  lines.push(`  ${JSON.stringify(c.name)},`);
  lines.push(`  { providers: ${c.targets.box ? "Layer.mergeAll(Cloudflare.providers(), Hetzner.providers())" : "Cloudflare.providers()"}, state: Alchemy.localState() },`);
  lines.push(`  Effect.gen(function* () {`);
  if (c.worker.build) lines.push(`    yield* Build;`);
  lines.push(`    const worker = yield* Worker;`);
  if (c.targets.box) lines.push(`    const service = yield* Service;`);
  lines.push(`    return { url: worker.url${c.targets.box ? ", box: service.url" : ""} };`);
  lines.push(`  }),`);
  lines.push(`);`);
  return lines.join("\n") + "\n";
}
